<section class="heroes">
  <header class="heroes__header">
    <h1 class="heroes__title">Roster</h1>
  </header>

  <section class="heroes__panel" aria-label="Hero roster">
    <div class="heroes__filters">
      <label hlmLabel for="roster-search" class="heroes__sr-only">Search heroes</label>
      <div class="heroes__search">
        <ng-icon name="lucideSearch" class="heroes__search-icon" aria-hidden="true" />
        <input
          hlmInput
          id="roster-search"
          #search
          type="search"
          class="heroes__search-input"
          placeholder="Search name, alias or ID"
          [value]="vm.query()"
          (input)="vm.setQuery(search.value)"
        />
      </div>

      <hlm-select
        class="heroes__class-filter"
        [value]="vm.powerClass()"
        (valueChange)="vm.setPowerClass($event)"
      >
        <hlm-select-trigger aria-label="Filter by power class">
          <hlm-select-value />
        </hlm-select-trigger>
        <hlm-select-content *hlmSelectPortal>
          <hlm-select-item value="all">All classes</hlm-select-item>
          @for (powerClass of vm.classOptions; track powerClass) {
            <hlm-select-item [value]="powerClass">{{ powerClass }}</hlm-select-item>
          }
        </hlm-select-content>
      </hlm-select>

      <a hlmBtn routerLink="/recruit" class="heroes__recruit">
        <ng-icon name="lucidePlus" aria-hidden="true" />
        Recruit
      </a>
    </div>

    <div hlmTableContainer class="heroes__table-wrap">
      <table hlmTable>
        <caption hlmTableCaption class="heroes__sr-only">
          Heroes on the roster, strongest first
        </caption>
        <thead hlmTableHeader>
          <tr hlmTableRow>
            <th hlmTableHead scope="col">Hero</th>
            <th hlmTableHead scope="col">Class</th>
            <th hlmTableHead scope="col" class="heroes__num">Power</th>
            <th hlmTableHead scope="col">Status</th>
            <th hlmTableHead scope="col">Clearance</th>
            <th hlmTableHead scope="col">Actions</th>
          </tr>
        </thead>
        <tbody hlmTableBody>
          @for (hero of vm.rows(); track hero.id) {
            <tr hlmTableRow>
              <td hlmTableCell>
                <div class="heroes__identity">
                  <hlm-avatar class="heroes__avatar" aria-hidden="true">
                    <span hlmAvatarFallback>{{ vm.initialsOf(hero.name) }}</span>
                  </hlm-avatar>
                  <div class="heroes__names">
                    <span class="heroes__name">{{ hero.name }}</span>
                    <span class="heroes__id">{{ hero.id }} · {{ hero.alias }}</span>
                  </div>
                </div>
              </td>
              <td hlmTableCell>
                <span hlmBadge variant="outline">{{ hero.powerClass }}</span>
              </td>
              <td hlmTableCell class="heroes__num">{{ hero.powerIndex }}</td>
              <td hlmTableCell>
                <span hlmBadge variant="secondary">
                  <span class="heroes__dot" [attr.data-status]="hero.status" aria-hidden="true"></span>
                  {{ hero.status }}
                </span>
              </td>
              <td hlmTableCell class="heroes__num">Tier {{ hero.clearanceTier }}</td>
              <td hlmTableCell>
                <a
                  hlmBtn
                  variant="ghost"
                  size="icon"
                  [routerLink]="['/detail', hero.id]"
                  [attr.aria-label]="'Edit ' + hero.name"
                >
                  <ng-icon name="lucidePencil" aria-hidden="true" />
                </a>
              </td>
            </tr>
          } @empty {
            <tr hlmTableRow>
              <td hlmTableCell colspan="6" class="heroes__empty">No heroes match these filters.</td>
            </tr>
          }
        </tbody>
      </table>
    </div>

    <footer class="heroes__footer">
      <p class="heroes__summary" aria-live="polite">
        {{ vm.rows().length }} of {{ vm.total() }} heroes
      </p>
      <p class="heroes__sort">Sorted by power</p>
    </footer>
  </section>
</section>
=== src/app/forms/zod-meta.ts
import type { z } from 'zod';
import type { FormFieldMeta } from './form-field-meta';

/**
 * Read the FormFieldMeta off each field of a zod object schema. Keeps the label,
 * control kind, and placeholder on the schema (one source of truth) so a form
 * component reads them instead of restating them. Pair with `validateStandardSchema`
 * from `@angular/forms/signals` for validation, so shape, rules, and labels all
 * live on the one schema.
 */
export function formMeta(schema: z.ZodObject<z.ZodRawShape>): Record<string, FormFieldMeta> {
  const meta: Record<string, FormFieldMeta> = {};
  for (const [name, field] of Object.entries(schema.shape)) {
    meta[name] = (field as z.ZodType).meta() as unknown as FormFieldMeta;
  }
  return meta;
}
=== src/app/forms/form-field-meta.ts
/**
 * Presentation metadata that rides on a zod field via `.meta()`. Strongly typed,
 * so a missing label is a compile error rather than a runtime surprise. A form
 * component reads this off the schema instead of restating labels and control
 * kinds in a parallel config object.
 */
export type ControlKind = 'text' | 'email' | 'number' | 'select' | 'checkbox' | 'textarea';

export interface FormFieldMeta {
  label: string;
  control: ControlKind;
  placeholder?: string;
  options?: ReadonlyArray<{ value: string; label: string }>;
  order?: number;
  help?: string;
}

