import { Directive, input } from '@angular/core';
import { BrnTabs } from '@spartan-ng/brain/tabs';
import { classes } from '@spartan-ng/helm/utils';

@Directive({
  selector: '[hlmTabs],hlm-tabs',
  hostDirectives: [
    {
      directive: BrnTabs,
      inputs: ['orientation', 'activationMode', 'brnTabs: tab'],
      outputs: ['tabActivated'],
    },
  ],
  host: {
    'data-slot': 'tabs',
  },
})
export class HlmTabs {
  public readonly tab = input.required<string>();

  constructor() {
    classes(() => 'group/tabs flex gap-2 data-[orientation=horizontal]:flex-col');
  }
}
---STAT
import { Component, input } from '@angular/core';
import { HlmBadgeImports } from '@spartan-ng/helm/badge';
import { HlmCardImports } from '@spartan-ng/helm/card';

/**
 * One headline figure. The icon is projected in by the screen, which registers it;
 * this component takes no data and injects nothing.
 */
@Component({
  selector: 'app-stat-tile',
  imports: [HlmCardImports, HlmBadgeImports],
  templateUrl: './stat-tile.html',
  styleUrl: './stat-tile.css',
})
export class StatTile {
  readonly label = input.required<string>();
  readonly value = input.required<string | number | null>();
  readonly hint = input<string>();
}
<article hlmCard class="stat-tile">
  <div hlmCardContent class="stat-tile__body">
    <div class="stat-tile__head">
      <span class="stat-tile__label">{{ label() }}</span>
      <span class="stat-tile__icon">
        <ng-content select="ng-icon" />
      </span>
    </div>
    <p class="stat-tile__value">{{ value() }}</p>
    @if (hint()) {
      <span hlmBadge variant="secondary" class="stat-tile__hint">{{ hint() }}</span>
    }
  </div>
</article>
@reference "../../styles.css";

.stat-tile { @apply h-full min-w-0; }
.stat-tile__body { @apply grid gap-3; }
.stat-tile__head { @apply flex items-center justify-between gap-3; }
.stat-tile__label { @apply min-w-0 text-sm text-muted-foreground wrap-break-word; }
.stat-tile__icon { @apply inline-flex size-8 shrink-0 items-center justify-center rounded-md bg-muted text-foreground; }
.stat-tile__value { @apply text-3xl font-semibold tabular-nums; }
.stat-tile__hint { @apply justify-self-start; }
---HC
@reference "../../styles.css";

.hero-card { @apply h-full min-w-0; }
.hero-card__header { @apply min-w-0; }
.hero-card__identity { @apply flex min-w-0 items-center gap-3; }
.hero-card__avatar { @apply shrink-0; }
.hero-card__names { @apply grid min-w-0 gap-0.5; }
.hero-card__name { @apply wrap-break-word; }
.hero-card__alias { @apply wrap-break-word; }
.hero-card__body { @apply grid gap-4; }
.hero-card__meta { @apply flex flex-wrap items-center gap-2; }
.hero-card__dot { @apply inline-block size-2 shrink-0 rounded-full; background: var(--muted-foreground); }
.hero-card__dot[data-status='Active'] { background: var(--success); }
.hero-card__dot[data-status='Injured'] { background: var(--warning); }
.hero-card__dot[data-status='MIA'] { background: var(--destructive); }
---PM
<div class="power-meter">
  <div class="power-meter__head">
    <span>Power</span>
    <span class="power-meter__value">{{ value() }}</span>
  </div>
